 descriptionIndex = 2
 }
 if (setVariationIndex == 4) {
 descriptionIndex = 2
 setVariationIndex = 1
 weights = completedWeights[1] * 0.85
 rm1 = completedWeights[1] / rpeMultiplier(5, 10)
 } else if (completedReps >= reps) {
 weights = completedWeights[ns] + state.increase
