{"id": "pzerofullbody", "text": "# Week 1
## Workout A1
// ...T1
T1: Deadlift / ...T1

// ...T2
T2: Bench Press / ...T2

// ...T3
T3: T Bar Row / ...T3

// ...T3
T3: Leg Press / ...T3

// ...T3
T3: Chest Dip / ...T3

// ...T3
T3: Cable Crunch / ...T3

## Workout B1
// ...T1
T1: Overhead Press / ...T1

// ...T2
T2: Squat / ...T2

// ...T3
T3: Pull Up / ...T3

// ...T3
T3: Incline Bench Press, Dumbbell / ...T3

// ...T3
T3: Seated Leg Curl / ...T3

// ...T3
T3: Bicep Curl / ...T3

## Workout A2
// ...T1
T1: Bench Press / ...T1

// ...T2
T2: Deadlift / ...T2

// ...T3
T3: Seated Row / ...T3

// ...T3
T3: Shoulder Press / ...T3

// ...T3
T3: Leg Extension / ...T3

// ...T3
T3: Side Crunch, Cable / ...T3

## Workout B2
// ...T1
T1: Squat / ...T1

// ...T2
T2: Overhead Press / ...T2

// ...T3
T3: Romanian Deadlift, Barbell / ...T3

// ...T3
T3: Bench Press, Dumbbell / ...T3

// ...T3
T3: Lateral Raise, Cable / ...T3

// ...T3
T3: Flat Leg Raise / ...T3



// **T1**. Set your 1RM before start.

// **T1**.
T1 / used: none / 3x4, 1x5+ / 3x3, 1x4+ / 3x2, 1x3+ / 72% / progress: custom(increase: 5lb, stage1weight: 0lb) {~
 if (descriptionIndex == 1) {
 descriptionIndex = 2
 }
 if (setVariationIndex == 1) {
 state.stage1weight = weights[ns]
 }
 weights += state.increase
 if (completedReps[ns] < reps[ns]) {
 if (setVariationIndex == 3) {
 setVariationIndex = 1
 weights = state.stage1weight + state.increase
 } else {
 setVariationIndex += 1
 }
 }
~}


// **T2**. Set your 1RM before start.

// **T2**.
T2 / used: none / 4x12 / 4x10 / 4x8 / 52% 120s / progress: custom(increase: 5lb, stage1weight: 0lb) {~
 if (descriptionIndex == 1) {
 descriptionIndex = 2
 }
 if (setVariationIndex == 1) {
 state.stage1weight = weights[ns]
 }
 weights += state.increase
 if (!(completedReps >= reps)) {
 if (setVariationIndex == 3) {
 setVariationIndex = 1
 weights = state.stage1weight + state.increase
 } else {
 setVariationIndex += 1
 }
 }
~}


// **T3**. You need to get total reps indicated by max reps in range in
// as few sets as possible. Complete a set with some reps, then add another
// set and complete again. If you do all required reps in <= 4 sets, weight goes up.
// If more than 4 sets - it goes to the next stage (dropping the goal reps)
T3 / used: none / 1x1-60+ / 50% 90s / progress: custom(increase: 5lb, initialReps: 60, diff: 15, stage1weight: 0lb) {~
 if (reps[ns] == state.initialReps) {
 state.stage1weight = weights[ns]
 }
 if (sum(completedReps) >= reps[ns]) {
 if (completedNumberOfSets <= 4) {
 weights += state.increase
 } else {
 if (reps[ns] == state.initialReps - state.diff * 2) {
 weights = state.stage1weight + state.increase
 reps = state.initialReps
 } else {
 reps -= state.diff
 }
 }
 }
~}

// **T1 Ultra**.
// It asks you if want to go switch to the next stage at the end (0 - keep, 1 - switch).
// Switch to the next stage if the last set is significantly slower than first one.
T1Ultra / used: none / 3x1 / 2x1 / 1x1 / 90% / progress: custom(increase: 5lb, nextstage+: 0) {~
 weights += state.increase
 if (state.nextstage > 0) {
 setVariationIndex += 1
 }
~}", "weeks": [["Workout A1", "Workout B1", "Workout A2", "Workout B2"]], "problem": null}

{"id": "recommended-routine", "text": "# Week 1
## Day 1
/// Rep ladders: add a rep each session; at the top of the range graduate to the next movement, or
/// on the final rung add weight. With `addWeight: 0lb` the final rung stays at the top of the range.
rrProgress / used: none / 3x5 0lb / 90s / warmup: none / progress: custom(topVar: 4, addWeight: 5lb, minReps: 5, maxReps: 8) {~
 if (completedReps >= reps) {
 if (reps >= state.maxReps) {
 if (exerciseVariationIndex < state.topVar) {
 exerciseVariationIndex += 1
 reps = state.minReps
 } else if (state.addWeight > 0lb) {
 weights += state.addWeight
 reps = state.minReps
 }
 } else {
 reps += 1
 }
 }
~}

/// Ladders that contain a timed isometric hold. Set variation 1 = timed hold, set variation 2 = reps;
/// `holdRung` is which movement in the ladder is the hold. On the hold you add 5s each session until the
/// holdTarget (then graduate); on the rep rungs you add a rep. The set scheme flips when you cross the hold.
rrHold / used: none / 3x1 0lb 20s|60s / 3x8 0lb 60s / warmup: none / progress: custom(topVar: 4, holdRung: 2, holdTarget: 30, minReps: 5, maxReps: 8, addWeight: 5lb) {~
 if (exerciseVariationIndex == state.holdRung) {
 setVariationIndex = 1
 if (completedSetTime >= setTime) {
 if (setTime >= state.holdTarget && exerciseVariationIndex < state.topVar) {
 exerciseVariationIndex += 1
 setVariationIndex = 2
 } else {
 setTime[*:*:1:*] += 5
 }
 }
 } else {
 setVariationIndex = 2
 if (completedReps >= reps) {
 if (reps >= state.maxReps) {
 if (exerciseVariationIndex < state.topVar) {
 var.next = exerciseVariationIndex + 1
 exerciseVariationIndex = var.next
 setVariationIndex = var.next == state.holdRung ? 1 : 2
 reps[*:*:2:*] = state.minReps
 } else if (state.addWeight > 0lb) {
 weights += state.addWeight
 reps[*:*:2:*] = state.minReps
 }
 } else {
 reps[*:*:2:*] += 1
 }
 }
 }
~}

// **Warm-up (5-10 min).** Also do squat sky reaches and wrist prep. Add arch hangs once you reach
// Negative Pull Ups, support holds once you reach Negative Dips, easier squats once you reach
// Bulgarian Split Squats, and easier hinges once you reach banded Nordic Curls.
Shoulder Pass Through / 1x10 / 30s / warmup: none

Dead Bug / 1x1 30s|30s / warmup: none

// **First Pair.** Pull-up progression - vertical pull. Pick the hardest rung you can do for 3x5, add a rep
// each session, graduate at 3x8. Arch Hang is a timed hold - hold 20-30s per set, graduate at 30s.
Scapular Pull Up | Arch Hang | Negative Pull Up | Pull Up / 3x1 0lb 20s|90s / ! 3x5 0lb 90s / warmup: none / superset: A / progress: custom(topVar: 4, holdRung: 2) { ...rrHold }

// Squat progression. On Shrimp Squats, work from beginner (knee and toes leave the floor together) to
// intermediate (only the knee touches) to advanced (hold your heel) before you add weight.
// *If you have a barbell, swap this for barbell Squats once you've mastered the basic squat.*
Assisted Squat | Squat, Bodyweight | Split Squat, Bodyweight | Bulgarian Split Squat, Bodyweight | Shrimp Squat / 3x5 0lb / 90s / warmup: none / superset: A / progress: custom(topVar: 5, addWeight: 10lb) { ...rrProgress }

// **Second Pair.** Dip progression - vertical push. Support Hold is a timed hold - build up to 60s, then
// move to Negative Dips.
Support Hold | Negative Dip | Chest Dip / 3x1 0lb 20s|90s / 3x5 0lb 90s / warmup: none / superset: B / progress: custom(topVar: 3, holdRung: 1, holdTarget: 60) { ...rrHold }

// Hinge progression - hamstrings and glutes. Banded Nordic Curls: start with negatives only (lower slowly,
// push back up with your hands), then do full reps, then use lighter bands until you can do them without one.
// *With a barbell, swap for Romanian Deadlifts / Deadlifts.*
